use gba_core::{Machine,Bus};
fn main(){let mut m=Machine::new(std::fs::read(std::env::args().nth(1).unwrap()).unwrap());for(n,d)in[("ewram",&mut m.bus.ewram),("iwram",&mut m.bus.iwram),("vram",&mut m.bus.vram),("io",&mut m.bus.io),("oam",&mut m.bus.oam),("palette",&mut m.bus.palette)]{d.copy_from_slice(&std::fs::read(format!("target/card-keeper-4000-{n}.bin")).unwrap());}m.bus.ffta_movement.enabled=true;m.bus.ffta_movement.europe_profile=true;m.bus.ffta_dialogue.separate=true;m.bus.ewram[0x7f10..0x7f12].copy_from_slice(&66u16.to_le_bytes());let manager=m.bus.read32(0x0200f428);let base=manager+0xce8;m.bus.write32(base,0x0805aee5);m.bus.write32(base+4,0x0805e7b5);m.bus.write8(base+8,2);m.bus.write8(base+9,2);m.cpu.cpsr=0xbf;m.cpu.regs[13]=0x03007b00;m.cpu.regs[14]=0x08000001;m.cpu.regs[15]=0x0805aee4;m.cpu.regs[0]=0;m.cpu.regs[1]=base+8;m.cpu.branch=None;for _ in 0..2000000 {if m.cpu.regs[15]==0x0805b104{m.cpu.regs[0]=5;}if m.cpu.regs[15]==0x08000000{break;}m.step();}m.bus.write16(base+0x2c,6);m.bus.write16(base+0x2e,7);
m.cpu.cpsr=0xbf;m.cpu.regs[13]=0x03007b00;m.cpu.regs[14]=0x08000001;m.cpu.regs[15]=0x0805aee4;m.cpu.regs[0]=0;m.cpu.regs[1]=base+8;m.cpu.branch=None;
for _ in 0..2000000 {if m.cpu.regs[15]==0x08000000{break;}m.step();}
m.bus.ffta_battle_mouse.enable_replay();gba_core::mem::set_extra(22);for y in 0..160{gba_core::ppu::render_scanline(&mut m.bus,y);}
println!("BANK_MENU {:?} UI {:?}",gba_core::ffta_battle_mouse::MenuScene::read(&m.bus),gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue));
for target in [1,0,1]{assert!(gba_core::ffta_battle_mouse::menu_select(&mut m.bus,target,false));assert_eq!(gba_core::ffta_battle_mouse::MenuScene::read(&m.bus).unwrap().selected,target);assert_eq!(gba_core::ffta_battle_mouse::keys(&mut m.bus,0x3ff),0x3ff);m.bus.ffta_battle_mouse.cancel();println!("BANK direct target={target}");}
for(current,target)in[(0u16,6u16),(2,6),(6,6),(6,0),(1,0)]{m.bus.write16(base+0x2c,current);m.bus.write16(base+0x30,target);let w=gba_core::ffta_ui_window::pub_windows(&m.bus,[None;3])[0].unwrap();assert_eq!(w.bounds,[0,72,56,128]);assert!(w.visible());println!("BANK animation current={current} target={target} fixed=true");}
println!("DONE pc={:x} base={base:x}",m.cpu.regs[15]);for o in (0..m.bus.ewram.len()-44).step_by(4){if m.bus.ewram[o..o+8]==[0,0x58,0,6,0,0x50,0,6]{println!("WINDOW {o:x} rect={:?} body={:02x?}",&m.bus.ewram[o+16..o+20],&m.bus.ewram[o+20..o+44]);}}for(n,d)in[("ewram",&m.bus.ewram),("iwram",&m.bus.iwram),("vram",&m.bus.vram),("io",&m.bus.io),("oam",&m.bus.oam),("palette",&m.bus.palette)]{std::fs::write(format!("target/bank-constructor-{n}.bin"),d).unwrap();}}

